import React, { useState, useEffect, useRef } from "react"
import { motion } from "framer-motion"
import { addPropertyControls, ControlType } from "framer"
import styled from "styled-components"

const NumberCounterStyles = {
    container: {
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
    },
}

const useForceInlineStyles = (ref, styles) => {
    useEffect(() => {
        if (ref.current && styles) {
            // Use a small timeout to ensure it runs after Framer styling
            const timeoutId = setTimeout(() => {
                // Apply each style as an inline style with !important
                Object.entries(styles).forEach(([property, value]) => {
                    ref.current.style.setProperty(property, value, "important")
                })
            }, 50)

            return () => clearTimeout(timeoutId)
        }
    }, [ref, styles])
}

// Convert to a functional component that uses the hook
const CounterText = (props) => {
    const spanRef = useRef(null)

    // Extract all style props
    const { font, fontType, color, verticalAlign, children, ...otherProps } =
        props

    // Determine the final style values
    const fontFamily =
        props.fontFamily ||
        (font && font.fontFamily) ||
        (fontType && fontType.fontFamily) ||
        "Inter"

    const fontSize =
        props.fontSize ||
        (font && font.fontSize) ||
        (fontType && fontType.fontSize) ||
        "16px"

    const fontWeight =
        props.fontWeight ||
        (font && font.fontWeight) ||
        (fontType && fontType.fontWeight) ||
        400

    const lineHeight =
        props.lineHeight ||
        (font && font.lineHeight) ||
        (fontType && fontType.lineHeight) ||
        "1.2"

    const letterSpacing =
        props.letterSpacing ||
        (font && font.letterSpacing) ||
        (fontType && fontType.letterSpacing) ||
        "normal"

    const textAlign =
        props.textAlign ||
        (font && font.textAlign) ||
        (fontType && fontType.textAlign) ||
        "left"

    const fontStyle =
        props.fontStyle ||
        (font && font.fontStyle) ||
        (fontType && fontType.fontStyle) ||
        "normal"

    // Create a style object for our hook
    const styles = {
        color: color || "#000",
        "font-family": fontFamily,
        "font-size": fontSize,
        "font-weight": fontWeight.toString(),
        "line-height": lineHeight,
        "letter-spacing": letterSpacing,
        "text-align": textAlign,
        "font-style": fontStyle,
        padding: "0",
        margin: "0",
        "box-sizing": "content-box",
        "white-space": "nowrap",
        display: "inline-block",
    }

    // Handle vertical alignment
    let alignSelf = "baseline"
    switch (verticalAlign) {
        case "top":
            alignSelf = "flex-start"
            break
        case "middle":
            alignSelf = "center"
            break
        case "bottom":
            alignSelf = "flex-end"
            break
        default:
            alignSelf = "baseline"
    }
    styles["align-self"] = alignSelf

    // Use our hook to force these styles
    useForceInlineStyles(spanRef, styles)

    return (
        <span ref={spanRef} {...otherProps}>
            {children}
        </span>
    )
}

/**
 * @framerDisableUnlink
 */
export function NumberCounter(props) {
    const {
        start,
        end,
        speed,
        gapSize,
        prefixText,
        suffixText,
        prefixFont,
        suffixFont,
        prefixColor,
        suffixColor,
        prefixPosition,
        suffixPosition,
        loop,
        decimalSep,
        textSize,
        fontType,
        textColor,
        replayCount,
        loopCount,
        incrementType,
        formatType,
        uppercaseRoman,
    } = props

    const [count, setCount] = useState(start)
    const [isVisible, setIsVisible] = useState(false)
    const [hasStarted, setHasStarted] = useState(false)
    const containerRef = useRef(null)
    const prevVisibleRef = useRef(false)

    useEffect(() => {
        const observer = new IntersectionObserver((entries) => {
            setIsVisible(entries[0].isIntersecting)
        })

        if (containerRef.current) {
            observer.observe(containerRef.current)
        }

        return () => {
            if (containerRef.current) {
                observer.unobserve(containerRef.current)
            }
        }
    }, [])

    // Reset counter when necessary
    useEffect(() => {
        // Start counting when component becomes visible
        if (isVisible && !hasStarted) {
            setCount(start)
            setHasStarted(true)
        }

        // Reset counter for loop functionality
        if (isVisible && !prevVisibleRef.current && loopCount && hasStarted) {
            setCount(start)
        }

        prevVisibleRef.current = isVisible
    }, [isVisible, start, loopCount, hasStarted])

    // Handle the counting logic
    useEffect(() => {
        // Only count when visible in the viewport
        const shouldCount = isVisible && hasStarted

        if (shouldCount) {
            const step = incrementType === "integer" ? 1 : 0.1
            const timer = setInterval(() => {
                setCount((prev) => {
                    const next = parseFloat((prev + step).toFixed(2))
                    return next >= end ? end : next
                })
            }, speed)

            return () => clearInterval(timer)
        }
    }, [count, end, isVisible, speed, incrementType, hasStarted])

    // Handle looping
    useEffect(() => {
        if (loop && count >= end) {
            const loopTimer = setTimeout(() => {
                setCount(start)
            }, 1000)
            return () => clearTimeout(loopTimer)
        }
    }, [count, end, loop, start])

    const toRoman = (num) => {
        if (num <= 0) return "N/A"
        if (num >= 4000) return num.toString()

        const romanNumerals = [
            { value: 1000, numeral: "M" },
            { value: 900, numeral: "CM" },
            { value: 500, numeral: "D" },
            { value: 400, numeral: "CD" },
            { value: 100, numeral: "C" },
            { value: 90, numeral: "XC" },
            { value: 50, numeral: "L" },
            { value: 40, numeral: "XL" },
            { value: 10, numeral: "X" },
            { value: 9, numeral: "IX" },
            { value: 5, numeral: "V" },
            { value: 4, numeral: "IV" },
            { value: 1, numeral: "I" },
        ]

        let result = ""
        let remaining = Math.floor(num)

        for (const { value, numeral } of romanNumerals) {
            while (remaining >= value) {
                result += numeral
                remaining -= value
            }
        }

        return uppercaseRoman ? result : result.toLowerCase()
    }

    const formatNumber = (num) => {
        if (formatType === "roman") {
            return toRoman(num)
        } else if (decimalSep === "period") {
            return num.toLocaleString("de-DE", {
                minimumFractionDigits: incrementType === "integer" ? 0 : 1,
            })
        } else if (decimalSep === "comma") {
            return num.toLocaleString("en-US", {
                minimumFractionDigits: incrementType === "integer" ? 0 : 1,
            })
        } else {
            return num.toFixed(incrementType === "integer" ? 0 : 1)
        }
    }

    return (
        <motion.div
            ref={containerRef}
            style={{
                ...NumberCounterStyles.container,
                gap: `${gapSize}px`,
                flexDirection: "row",
                alignItems: "center",
                display: "flex",
            }}
        >
            <CounterText
                font={prefixFont}
                fontType={prefixFont}
                color={prefixColor}
                verticalAlign={prefixPosition}
            >
                {prefixText}
            </CounterText>
            <CounterText font={fontType} fontType={fontType} color={textColor}>
                {formatNumber(count)}
            </CounterText>
            <CounterText
                font={suffixFont}
                fontType={suffixFont}
                color={suffixColor}
                verticalAlign={suffixPosition}
            >
                {suffixText}
            </CounterText>
        </motion.div>
    )
}

NumberCounter.defaultProps = {
    start: 1,
    end: 100,
    speed: 100,
    prefixText: "",
    suffixText: "",
    prefixPosition: "baseline",
    suffixPosition: "baseline",
    loop: false,
    decimalSep: "comma",
    formatType: "numeric",
    uppercaseRoman: true,
    fontType: {
        fontFamily: "Inter",
        fontSize: 36,
        fontWeight: 500,
        lineHeight: "1.2",
        letterSpacing: "normal",
        textAlign: "center",
        fontStyle: "normal",
        systemFont: true,
    },
    textColor: "#D3D3D3",
    replayCount: false,
    incrementType: "integer",
}

